-- Migration: Create renovation_pricing_reports table
-- This table stores the pricing reports generated by the renovation-pricing endpoint

CREATE TABLE IF NOT EXISTS renovation_pricing_reports (
    id BIGSERIAL PRIMARY KEY,
    listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
    report_data JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Ensure one pricing report per listing
    UNIQUE(listing_id)
);

-- Add indexes for performance
CREATE INDEX IF NOT EXISTS idx_renovation_pricing_reports_listing_id ON renovation_pricing_reports(listing_id);
CREATE INDEX IF NOT EXISTS idx_renovation_pricing_reports_created_at ON renovation_pricing_reports(created_at);

-- Add RLS policies
ALTER TABLE renovation_pricing_reports ENABLE ROW LEVEL SECURITY;

-- Allow public read access
CREATE POLICY "Allow public read access to renovation_pricing_reports" ON renovation_pricing_reports
    FOR SELECT USING (true);

-- Allow service role full access
CREATE POLICY "Allow service role full access to renovation_pricing_reports" ON renovation_pricing_reports
    FOR ALL USING (auth.role() = 'service_role');

-- Add trigger for updated_at
CREATE OR REPLACE FUNCTION update_renovation_pricing_reports_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_renovation_pricing_reports_updated_at
    BEFORE UPDATE ON renovation_pricing_reports
    FOR EACH ROW
    EXECUTE FUNCTION update_renovation_pricing_reports_updated_at();
